/*
 * Web Push for the IAPP service worker.
 *
 * The worker itself is generated by Workbox (vite-plugin-pwa, generateSW), so
 * there is no source file to add listeners to. vite.config.ts lists this file
 * in workbox.importScripts instead: the generated sw.js loads it on start and
 * these listeners run next to Workbox's caching, which is left untouched.
 *
 * Plain JS on purpose: it is copied from public/ as-is, never bundled.
 *
 * Payload sent by the server: { title, body, url, tag? }.
 */

/* global self, clients */

const ICON = '/pwa-192x192.png'

function readPayload(event) {
  if (!event.data) return {}
  try {
    return event.data.json() || {}
  } catch {
    // Not JSON (a test push from DevTools, say): show the text as the body.
    return { body: event.data.text() }
  }
}

self.addEventListener('push', (event) => {
  const data = readPayload(event)
  // Always show something. A push the worker swallows without a notification
  // counts against the site, and Safari revokes the subscription for it.
  event.waitUntil(
    self.registration.showNotification(data.title || 'IAPP', {
      body: data.body || '',
      tag: data.tag || undefined,
      // The same tag replaces the earlier notification; renotify still buzzes,
      // or a second digest would arrive silently.
      renotify: Boolean(data.tag),
      icon: ICON,
      badge: ICON,
      data: { url: data.url || '/' },
    }),
  )
})

/** Only our own pages: a URL in a payload must never open someone else's site. */
function sameOriginUrl(raw) {
  try {
    const url = new URL(raw || '/', self.location.origin)
    return url.origin === self.location.origin ? url.href : self.location.origin + '/'
  } catch {
    return self.location.origin + '/'
  }
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const url = sameOriginUrl(event.notification.data && event.notification.data.url)

  event.waitUntil(
    (async () => {
      const windows = await clients.matchAll({ type: 'window', includeUncontrolled: true })
      const client = windows.find((c) => c.focused) || windows.find((c) => c.visibilityState === 'visible') || windows[0]
      if (!client) {
        await clients.openWindow(url)
        return
      }
      await client.focus()
      if (client.url === url) return
      // Routed in place by the open app (core/notifications/usePushBridge)
      // rather than client.navigate(), which reloads the whole app and would
      // throw away a form someone is half-way through.
      client.postMessage({ type: 'iapp:navigate', url })
    })().catch(() => clients.openWindow(url)),
  )
})

/*
 * The browser rotated the subscription (it expired, or the push service
 * dropped it). The worker has no session token, so it cannot tell the server;
 * it only resubscribes so pushes keep a live endpoint, and the app re-sends
 * the subscription the next time it starts (usePushBridge). The old endpoint
 * starts answering 410 and the server prunes it.
 */
self.addEventListener('pushsubscriptionchange', (event) => {
  const options = event.oldSubscription && event.oldSubscription.options
  if (event.newSubscription || !options || !options.applicationServerKey) return
  event.waitUntil(
    self.registration.pushManager
      .subscribe({ userVisibleOnly: true, applicationServerKey: options.applicationServerKey })
      .catch(() => {}),
  )
})
